#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step151-$TS"
echo "==> step151: login / signup popups (#4)"
echo "    backup: $BK"
mkdir -p "$BK/views/partials" "$BK/routes"
cp "$GSZ/views/partials/store_bottom.ejs" "$BK/views/partials/" 2>/dev/null || true
cp "$GSZ/routes/account.js"               "$BK/routes/"          2>/dev/null || true

restore(){ echo "!! error — restoring from backup"; cp "$BK/views/partials/store_bottom.ejs" "$GSZ/views/partials/" 2>/dev/null || true; cp "$BK/routes/account.js" "$GSZ/routes/" 2>/dev/null || true; }
trap 'restore' ERR

PATCHER=$(mktemp /tmp/patch_step151.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"

echo "==> applying"
NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"

echo "==> validating"
node --check "$GSZ/routes/account.js"
NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$GSZ/views/partials/store_bottom.ejs','utf8'),{filename:'$GSZ/views/partials/store_bottom.ejs'});console.log('    ejs ok')"

echo "==> restarting"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
if [ "$CODE" != "200" ]; then echo "    homepage $CODE after ${i}s"; false; fi
echo "    homepage 200: OK (after ${i}s)"

rm -f "$PATCHER"
trap - ERR
echo ""
echo "==> step151 OK  Login & Sign-up now open as clean popups anywhere on the store — no page jumps. Errors show inside the popup; success drops you straight into your account. (Hard-refresh once.)"
